import{_ as p,a0 as l,w as o,s as d,ao as r,I as n,x as t,a1 as a,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何發現截斷的數據項 | LCTT x X-CMD","titleTemplate":false,"description":"如何發現截斷的數據項 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何發現截斷的數據項 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何發現截斷的數據項 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20180704 BASHing data- Truncated data items","title":"如何發現截斷的數據項","tag":"201909","desc":""},"relativePath":"201909/20180704 BASHing data- Truncated data items.md","filePath":"[post].md"}'),g={name:"201909/20180704 BASHing data- Truncated data items.md"};function h(u,s,c,k,m,b){const i=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何發現截斷的數據項" tabindex="-1">如何發現截斷的數據項 <a class="header-anchor" href="#如何發現截斷的數據項" aria-label="Permalink to “如何發現截斷的數據項”">​</a></h1><p><strong>截斷</strong>（形容詞）：縮寫、刪節、縮減、剪切、剪裁、裁剪、修剪……</p><p>數據項被截斷的一種情況是將其輸入到資料庫字段中，該字段的字符限制比數據項的長度要短。例如，字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Yarrow Ravine Rattlesnake Habitat Area, 2 mi ENE of Yermo CA</span></span></code></pre></div><p>是 60 個字符長。如果你將其輸入到具有 50 個字符限制的“位置”字段，則可以獲得：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Yarrow Ravine Rattlesnake Habitat Area, 2 mi ENE #末尾帶有一個空格</span></span></code></pre></div><p>截斷也可能導致數據錯誤，比如你打算輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Sally Ann Hunter (aka Sally Cleveland)</span></span></code></pre></div><p>但是你忘記了閉合的括號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Sally Ann Hunter (aka Sally Cleveland</span></span></code></pre></div><p>這會讓使用數據的用户覺得 Sally 是否有被修剪掉了數據項的其它的別名。</p><p>截斷的數據項很難檢測。在審核數據時，我使用三種不同的方法來查找可能的截斷，但我仍然可能會錯過一些。</p><p><strong>數據項的長度分佈。</strong>第一種方法是捕獲我在各個字段中找到的大多數截斷的數據。我將字段傳遞給 <code>awk</code> 命令，該命令按字段寬度計算數據項，然後我使用 <code>sort</code> 以寬度的逆序打印計數。例如，要檢查以 <code>tab</code> 分隔的文件 <code>midges</code> 中的第 33 個字段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awk -F&quot;\\t&quot; &#39;NR&gt;1 {a[length($33)]++} \\</span></span>
<span class="line"><span>    END {for (i in a) print i FS a[i]}&#39; midges | sort -nr</span></span></code></pre></div><p><img src="https://www.polydesmida.info/BASHing/img1/2018-07-04_1.png" alt="distro1"></p><p>最長的條目恰好有 50 個字符，這是可疑的，並且在該寬度處存在數據項的“凸起”，這更加可疑。檢查這些 50 個字符的項目會發現截斷：</p><p><img src="https://www.polydesmida.info/BASHing/img1/2018-07-04_2.png" alt="distro2"></p><p>我用這種方式檢查的其他數據表有 100、200 和 255 個字符的“凸起”。在每種情況下，這種“凸起”都包含明顯的截斷。</p><p><strong>未匹配的括號。</strong>第二種方法查找類似 <code>...(Sally Cleveland</code> 的數據項。一個很好的起點是數據表中所有標點符號的統計。這裏我檢查文件 <code>mag2</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>grep -o &quot;[[:punct:]]&quot; file | sort | uniqc</span></span></code></pre></div><p><img src="https://www.polydesmida.info/BASHing/img1/2018-07-04_3.png" alt="punct"></p><p>請注意，<code>mag2</code> 中的開括號和閉括號的數量不相等。要查看發生了什麼，我使用 <code>unmatched</code> 函數，它接受三個參數並檢查數據表中的所有字段。第一個參數是文件名，第二個和第三個是開括號和閉括號，用引號括起來。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unmatched()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    awk -F&quot;\\t&quot; -v start=&quot;$2&quot; -v end=&quot;$3&quot; \\</span></span>
<span class="line"><span>        &#39;{for (i=1;i&lt;=NF;i++) \\</span></span>
<span class="line"><span>            if (split($i,a,start) != split($i,b,end)) \\</span></span>
<span class="line"><span>                print &quot;line &quot;NR&quot;, field &quot;i&quot;:\\n&quot;$i}&#39; &quot;$1&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果在字段中找到開括號和閉括號之間不匹配，則 <code>unmatched</code> 會報告行號和字段號。這依賴於 <code>awk</code> 的 <code>split</code> 函數，它返回由分隔符分隔的元素數（包括空格）。這個數字總是比分隔符的數量多一個：</p><p><img src="https://www.polydesmida.info/BASHing/img1/2018-07-04_4.png" alt="split"></p><p>這裏 <code>ummatched</code> 檢查 <code>mag2</code> 中的圓括號並找到一些可能的截斷：</p><p><img src="https://www.polydesmida.info/BASHing/img1/2018-07-04_5.png" alt="unmatched"></p><p>我使用 <code>unmatched</code> 來找到不匹配的圓括號 <code>()</code>、方括號 <code>[]</code>、花括號 <code>{}</code> 和尖括號 <code>&lt;&gt;</code>，但該函數可用於任何配對的標點字符。</p><p><strong>意外的結尾。</strong>第三種方法查找以尾隨空格或非終止標點符號結尾的數據項，如逗號或連字符。這可以在單個字段上用 <code>cut</code> 用管道輸入到 <code>grep</code> 完成，或者用 <code>awk</code> 一步完成。在這裏，我正在檢查以製表符分隔的表 <code>herp5</code> 的字段 47，並提取可疑數據項及其行號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cut -f47 herp5 | grep -n &quot;[ ,;:-]$&quot;</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>awk -F&quot;\\t&quot; &#39;$47 ~ /[ ,;:-]$/ {print NR&quot;: &quot;$47}&#39; herp5</span></span></code></pre></div><p><img src="https://www.polydesmida.info/BASHing/img1/2018-07-04_6.png" alt="herps5"></p><p>用於製表符分隔文件的 awk 命令的全字段版本是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awk -F&quot;\\t&quot; &#39;{for (i=1;i&lt;=NF;i++) if ($i ~ /[ ,;:-]$/) \\</span></span>
<span class="line"><span>    print &quot;line &quot;NR&quot;, field &quot;i&quot;:\\n&quot;$i}&#39; file</span></span></code></pre></div><p><strong>謹慎的想法。</strong>在我對字段進行的驗證測試期間也會出現截斷。例如，我可能會在“年”的字段中檢查合理的 4 位數條目，並且有個 <code>198</code> 可能是 198n？還是 1898 年？帶有丟失字符的截斷數據項是個謎。 作為數據審計員，我只能報告（可能的）字符損失，並建議數據編制者或管理者恢復（可能）丟失的字符。</p><hr>`,35)),n("p",null,[s[1]||(s[1]=t("via: ",-1)),a(i,{href:"https://www.polydesmida.info/BASHing/2018-07-04.html"},{default:e(()=>[...s[0]||(s[0]=[t("https://www.polydesmida.info/BASHing/2018-07-04.html",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=t("作者：",-1)),a(i,{href:"https://www.polydesmida.info/"},{default:e(()=>[...s[2]||(s[2]=[t("polydesmida",-1)])]),_:1}),s[7]||(s[7]=t(" 選題：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[t("lujun9972",-1)])]),_:1}),s[8]||(s[8]=t(" 譯者：",-1)),a(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[4]||(s[4]=[t("wxy",-1)])]),_:1}),s[9]||(s[9]=t(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[t("LCTT",-1)])]),_:1}),s[13]||(s[13]=t(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[t("Linux中國",-1)])]),_:1}),s[14]||(s[14]=t(" 榮譽推出",-1))])])}const C=p(g,[["render",h]]);export{w as __pageData,C as default};
